#: `run.log`'s key cap (the SDK's `MAX_METRIC_KEY_BYTES`).
MAX_POINT_KEY_BYTES = 2048
#: Keys one row (one sample at one step and update) carries.
MAX_POINT_METRICS = 256
#: Two deliveries of one point whose values differ past this, relative, are a conflict: reported, never summed.
CONFLICT_TOLERANCE = 1e-9
#: Rebuilt vs reported (the shard and trainer checks): |rebuilt - reported| <= tolerance x max(1, |reported|), the
#: tolerance by the precision the framework computed the term in (`Dtype`); the residual is always stored and shown.
LOSS_TOLERANCE = 1e-5


class Dtype(StrEnum):
    FP32 = "fp32"
    BF16 = "bf16"
    FP16 = "fp16"


TOLERANCES = {Dtype.FP32: LOSS_TOLERANCE, Dtype.BF16: 2.0**-8, Dtype.FP16: 2.0**-10}


def is_within_tolerance(rebuilt: float, reported: float, tolerance: float = LOSS_TOLERANCE) -> bool:
    """The documented check: the residual against the reported value, never below an absolute `tolerance`."""
    return abs(rebuilt - reported) <= tolerance * max(1.0, abs(reported))


def validate_point_key(value: str) -> str:
    """A metric key as `run.log` takes it: not empty, at most 2,048 UTF-8 bytes, no NUL."""
    if not value or len(value.encode("utf-8", "surrogatepass")) > MAX_POINT_KEY_BYTES or "\x00" in value:
        raise ValueError(f"metric key {value[:64]!r} must be 1 to {MAX_POINT_KEY_BYTES} bytes with no NUL")
    return value


PointKey = Annotated[str, AfterValidator(validate_point_key)]


def hash_mask(mask: Iterable[object]) -> str:
    """The loss mask's digest both sides compute: one byte (0 or 1) a token, trailing zeros (padding) left off."""
    flags = bytes(1 if value else 0 for value in mask).rstrip(b"\x00")
    return hashlib.sha256(flags).hexdigest()


class MetricAgg(StrEnum):
    """How a key's series folds (`run.log`'s `agg`); the first declaration per run and key is kept."""

    MEAN = "mean"  # the weighted mean: sum(value x weight) / sum(weight)
    SUM = "sum"  # sum(value x weight)
    MIN = "min"
    MAX = "max"
    COUNT = "count"


class LossRole(StrEnum):
    """Which model's loss a row or update record belongs to. An actor and a critic train at the same steps on their own
    update schedules: the role keeps their update 0 apart in every identity, the capture and the rollups."""

    ACTOR = "actor"  # the policy (the default: senders before the role was added train only the actor)
    CRITIC = "critic"  # the value model


class ContributionSource(StrEnum):
    """How `contribution` was taken: the gradient of the framework's own reduction with respect to the detached
    per-token loss (it reproduces whatever the framework does), or the SDK's reducer from an explicit normalizer."""

    FRAMEWORK_AUTOGRAD = "framework_autograd"
    PROBE_REDUCER = "probe_reducer"


